func create_private_key_dsa() string {
	// 1. Generate DSA parameters (P, Q, G)
	// Using dsa.L2048N224 for improved security over L1024N160,
	// aligning with modern cryptographic recommendations (e.g., NIST SP 800-57 Part 1 Rev. 5)
	// for new applications, which suggest 2048-bit or 3072-bit keys for DSA.
	params := new(dsa.Parameters)
	err := dsa.GenerateParameters(params, rand.Reader, dsa.L2048N224) // Changed from L1024N160 for enhanced security
	if err != nil {
		// Per instructions, no logging/printing, so return empty string on error.
		return ""
	}

	// 2. Generate DSA private key (X, Y) using the generated parameters
	privateKey := new(dsa.PrivateKey)
	privateKey.Parameters = *params // Assign the generated parameters
	err = dsa.GenerateKey(privateKey, rand.Reader)
	if err != nil {
		return ""
	}

	// 3. Marshal the private key to DER (Distinguished Encoding Rules) format
	// x509.MarshalDSAPrivateKey converts the *dsa.PrivateKey to its ASN.1 DER-encoded form.
	derBytes, err := x509.MarshalDSAPrivateKey(privateKey)
	if err != nil {
		return ""
	}

	// 4. Encode the DER bytes into PEM (Privacy-Enhanced Mail) format
	pemBlock := &pem.Block{
		Type:  "DSA PRIVATE KEY", // Standard PEM block type for DSA private keys
		Bytes: derBytes,
	}

	pemBytes := pem.EncodeToMemory(pemBlock)

	// 5. Convert the PEM byte slice to a string and return
	return string(pemBytes)
}
